window.SF_TERMS = {"antenna-3":{"t":"Antenna 3","f":"Flagellomere 1 (f1)","s":"AIII; antennal segment 3","x":"both","d":"First flagellomere, the first long segment of the antenna after scape and pedicel. Older keys number antennal segments from the scape, so &#x27;antenna 3&#x27; = f1, &#x27;antenna 4&#x27; = f2, &#x27;antenna 5&#x27; = f3. Lengths and ratios to the labrum are used in many couplets.","g":"glossary.html#antenna-3"},"flagellomeres":{"t":"Flagellomeres","f":"Flagellomeres fI–fXIV","s":"Antennomeres AIII–AXVI; antennal segments 3–16","x":"both","d":"The 14 segments of the antennal flagellum after the scape and pedicel, numbered fI–fXIV (older keys count from the scape: antennal segments 3–16, AIII–AXVI). Galati et al. 2017 recommend recording the lengths of fI, fII, fIII and fXII–fXIV, the position of the internal and external ascoids on fI, the ascoidal formula, and the number and position of papillae and simple setae.","g":"glossary.html#flagellomeres"},"ascoid":{"t":"Ascoid","f":"","s":"Geniculated spine","x":"both","d":"Hyaline sensory rod on the flagellomeres. Number per segment (antennal formula), length relative to the segment (e.g. asc/f2) and presence of spurs are diagnostic (e.g. <i>S. gemmea</i> and <i>S. raynali</i> have spurred ascoids).","g":"glossary.html#ascoid"},"papilla":{"t":"Papilla","f":"","s":"Hirsute glands; sensorial papillae","x":"both","d":"Small sensilla on the flagellomeres. Galati et al. 2017 name them by position: apical (ap), preapical (pap), median (mp), basal (bp), preascoidal (pasp) and spiniform papillae (sp) (Fig. 4); their number and position on each flagellomere are recorded in descriptions. A papilla on antenna 5 (fIII) separates <i>P. argentipes</i> from <i>P. philippinensis</i> in Lewis 1978.","g":"glossary.html#papilla"},"newstead-s-sensilla":{"t":"Newstead&#x27;s sensilla","f":"","s":"Newstead&#x27;s spines; Newstead&#x27;s sensory spines; Newstead&#x27;s modified spines; hyaline sensilla; Newstead scales; peg sensilla","x":"both","d":"Club-shaped sensilla (Ns) on the palp, usually grouped on p3 and in some species also on p2 to p5. Descriptions record their presence and position: scattered over p3, or concentrated on its basal part (Galati et al. 2017, Fig. 3). Their arrangement is used by Quate 1962 and Lewis 1978.","g":"glossary.html#newstead-s-sensilla"},"palpal-formula":{"t":"Palpal formula","f":"","s":"","x":"both","d":"The palp has five segments (p1–p5). The palpal formula lists them in order of increasing length, e.g. 1-2-4-3-5. Galati et al. 2017 recommend recording the lengths of p1–p5, the palpal formula, the presence and position of Newstead&#x27;s sensilla on p2 and p3, and the number of spiniform setae on p3 and p4.","g":"glossary.html#palpal-formula"},"labrum":{"t":"Labrum","f":"Labrum-epipharynx","s":"","x":"both","d":"The dorsal mouthpart. Its length is the standard against which antenna 3 and wing length are compared.","g":"glossary.html#labrum"},"cibarium":{"t":"Cibarium","f":"","s":"Buccal cavity","x":"both","d":"The chamber behind the mouthparts. Its armature (teeth, sclerotized area, arch) is the most-used character in female <i>Sergentomyia</i> keys.","g":"glossary.html#cibarium"},"hind-teeth":{"t":"Hind teeth","f":"Posterior teeth","s":"Horizontal teeth; cibarial teeth; main teeth","x":"female","d":"The main transverse row of teeth at the hind end of the cibarium. Counts and row shape (concave, convex, straight) are key characters.","g":"glossary.html#hind-teeth"},"fore-teeth":{"t":"Fore teeth","f":"Anterior teeth","s":"Vertical teeth; erect teeth; denticles","x":"female","d":"Smaller teeth in one or more rows in front of the hind teeth. Number of rows (e.g. &#x27;three rows of fore teeth&#x27;) is used in <i>Neophlebotomus</i> couplets.","g":"glossary.html#fore-teeth"},"pigment-patch":{"t":"Pigment patch","f":"Sclerotized area","s":"Pigmented area; pigment belt; plage pigmentée","x":"female","d":"Darkened area of the cibarium in front of the tooth row. Its shape (bifid tip, anterior projection, narrow/linear) is diagnostic.","g":"glossary.html#pigment-patch"},"cibarial-arch":{"t":"Cibarial arch","f":"Sclerotized arch","s":"Chitinous arch","x":"female","d":"Arched sclerite at the front of the cibarium; the distance between arch and teeth is used in Lewis 1978 couplet 168.","g":"glossary.html#cibarial-arch"},"notch":{"t":"Notch","f":"Notch of the ventral plate","s":"","x":"female","d":"A median notch at the hind end of the cibarial ventral plate; characteristic of the <i>S. babu</i> series.","g":"glossary.html#notch"},"pharynx":{"t":"Pharynx","f":"","s":"","x":"both","d":"Tube behind the cibarium. The hind part may carry an armature of teeth, scales, ridges or spicules, which is key for <i>Phlebotomus</i> subgenera and <i>Parrotomyia</i>.","g":"glossary.html#pharynx"},"pharyngeal-armature":{"t":"Pharyngeal armature","f":"Pharyngeal teeth","s":"Spines of pharynx","x":"both","d":"The teeth, scales or ridges lining the hind part of the pharynx.","g":"glossary.html#pharyngeal-armature"},"r2-r2-3":{"t":"R2/R2+3","f":"Wing index alpha/beta","s":"Wing index","x":"both","d":"Ratio of the length of vein section R2 (alpha) to R2+3 (beta). &#x27;R1 overlap&#x27; is the distance by which the tip of R1 passes the fork of R2+3.","g":"glossary.html#r2-r2-3"},"abdominal-tergites-2-6":{"t":"Abdominal tergites 2-6","f":"Tergites II-VI","s":"","x":"both","d":"In <i>Phlebotomus</i> the hairs on tergites 2-6 are erect and arise from large sockets; in <i>Sergentomyia</i> they are recumbent with small sockets. This is couplet 1 of most keys.","g":"glossary.html#abdominal-tergites-2-6"},"spermatheca":{"t":"Spermatheca","f":"","s":"Body of spermatheca","x":"female","d":"Paired sperm-storage organ. Segmented (ringed), striated, smooth capsule or tubular forms define subgenera.","g":"glossary.html#spermatheca"},"head-of-spermatheca":{"t":"Head of spermatheca","f":"Terminal knob","s":"Head; apical segment","x":"female","d":"The apical part of the spermatheca, sometimes on a narrow neck.","g":"glossary.html#head-of-spermatheca"},"spermathecal-ducts":{"t":"Spermathecal ducts","f":"Individual and common spermathecal ducts","s":"Ducts","x":"female","d":"Each spermatheca opens into an individual duct; these join into a common duct. Their lengths separate <i>P. shadenae</i>, <i>P. stantoni</i> and <i>P. hoepplii</i>.","g":"glossary.html#spermathecal-ducts"},"genital-furca":{"t":"Genital furca","f":"Genital fork","s":"Genital furca","x":"female","d":"Sclerite of the female genital chamber.","g":"glossary.html#genital-furca"},"coxite":{"t":"Coxite","f":"Gonocoxite","s":"Basistyle; basimere; coxite","x":"male","d":"Basal segment of the male clasper. Its basal process or tuft of hairs (brush) is diagnostic.","g":"glossary.html#coxite"},"style":{"t":"Style","f":"Gonostyle","s":"Dististyle; distimere; style","x":"male","d":"Distal segment of the clasper. Number and position of its spines (terminal, subterminal, near middle) are used at genus and subgenus level; <i>Sergentomyia</i> has an accessory seta.","g":"glossary.html#style"},"accessory-seta":{"t":"Accessory seta","f":"Accessory seta of gonostyle","s":"Setiform spine","x":"male","d":"Fine seta on the gonostyle of <i>Sergentomyia</i> (absent in <i>Phlebotomus</i>).","g":"glossary.html#accessory-seta"},"paramere":{"t":"Paramere","f":"","s":"Intermediate appendage; clasper; claspette","x":"male","d":"Middle appendage of the male genitalia. Number of lobes (simple, bilobed, trilobed) separates <i>Euphlebotomus</i> and <i>Anaphlebotomus</i> species.","g":"glossary.html#paramere"},"aedeagus":{"t":"Aedeagus","f":"Parameral sheath","s":"Aedeagal sheath; aedeagus; penis; gubernaculum","x":"male","d":"The sclerotized sheath through which the genital filaments emerge (older keys call it the aedeagus). Its tip shape is used in <i>Parrotomyia</i> and <i>Larroussius</i>.","g":"glossary.html#aedeagus"},"genital-filaments":{"t":"Genital filaments","f":"Aedeagal ducts","s":"Genital filaments; ejaculatory ducts; penal filaments","x":"male","d":"Paired ducts leaving the sperm pump. Their length relative to the pump is diagnostic (e.g. <i>P. shadenae</i> versus <i>P. stantoni</i>).","g":"glossary.html#genital-filaments"},"genital-pump":{"t":"Genital pump","f":"Sperm pump","s":"Ejaculatory pump; pompetta","x":"male","d":"Internal pump that the genital filaments leave. Used as the unit for filament length.","g":"glossary.html#genital-pump"},"surstyle":{"t":"Surstyle","f":"Epandrial lobe","s":"Lateral lobe; surstyle; lower gonapophysis","x":"male","d":"Lobe beside the gonocoxite. Terminal spines on it occur in subgenus <i>Phlebotomus</i>.","g":"glossary.html#surstyle"},"intra-abdominal-rods":{"t":"Intra-abdominal rods","f":"Hypandrial apodemes","s":"Sclerotized rods","x":"male","d":"Paired rods next to the sperm pump; characteristic of <i>Idiophlebotomus</i>.","g":"glossary.html#intra-abdominal-rods"},"anepimeron-scales":{"t":"Anepimeron scales","f":"Anepimeral scales","s":"","x":"both","d":"The anepimeron (anp) is a sclerite on the side of the thorax, behind the upper and lower anepisternum (Galati et al. 2017, Fig. 10). It may bear anepimeral setae (anps, Fig. 11), whose presence or absence is recorded in descriptions. In <i>Grassomyia</i> the anepimeron bears scales (or their sockets), which are counted in the Lewis 1987 <i>Grassomyia</i> key.","g":"glossary.html#anepimeron-scales"},"trumpet-glands":{"t":"Trumpet glands","f":"","s":"glandes en trompettes; trumpet-shaped glands","x":"male","d":"Small trumpet-shaped glandular structures on the abdominal tergites of males of <i>Chinius</i>: 40-50 on the antero-dorsal parts of tergites 4 and 5 in <i>Ch. barbazani</i>, also present in <i>Ch. junlianensis</i>; Depaquit et al. (2006) include them in the definition of the genus.","g":"glossary.html#trumpet-glands"},"a-antenna":{"t":"antenna","f":"","d":"Jointed sensory appendage of the head: scape, pedicel and 14 flagellomeres (fI–fXIV). Older keys number the segments from the scape, so antenna 3 = fI, antenna 4 = fII, antenna 5 = fIII.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-sc":{"t":"sc","f":"scape","d":"First (basal) segment of the antenna, short and cup-shaped.","g":"glossary.html#a-sc","l":""},"a-pe":{"t":"pe","f":"pedicel","d":"Second segment of the antenna, globular, between the scape and the first flagellomere.","g":"glossary.html#a-pe","l":""},"a-fi":{"t":"fI","f":"1st flagellomere","d":"The first long antennal segment after scape and pedicel = &#x27;antenna 3&#x27; (A3, AIII) of older keys. Its length, often compared with the labrum, is used in many couplets.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-fii":{"t":"fII","f":"2nd flagellomere","d":"= &#x27;antenna 4&#x27; of older keys. Ascoid length is often expressed relative to it (asc/f2).","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-fxi-xiv":{"t":"fXI–fXIV","f":"apical flagellomeres","d":"The last four flagellomeres, shorter than the basal ones. Presence of ascoids and papillae on them is used in some keys.","g":"glossary.html#flagellomeres","l":"Flagellomeres"},"a-asc-f2":{"t":"asc/f2","f":"ascoid length / 2nd flagellomere length","d":"Ratio of the length of the ascoid to the length of flagellomere 2 (antenna 4).","g":"glossary.html#ascoid","l":"Ascoid"},"a-a3-e":{"t":"A3/E","f":"antenna 3 / labrum (epipharynx) ratio","d":"Length of flagellomere 1 (antenna 3) divided by the length of the labrum-epipharynx (E). A value below 1 means antenna 3 is shorter than the labrum.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-palp":{"t":"palp","f":"maxillary palp (palpus)","d":"Five-segmented sensory appendage beside the proboscis (p1–p5). The order of the segments by length gives the palpal formula, e.g. 1-2-4-3-5.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p1":{"t":"p1","f":"1st palpal segment","d":"Basal segment of the palp, usually the shortest.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p2":{"t":"p2","f":"2nd palpal segment","d":"Second segment of the palp.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p3":{"t":"p3","f":"3rd palpal segment","d":"Third segment of the palp; carries the Newstead&#x27;s sensilla.","g":"glossary.html#newstead-s-sensilla","l":"Newstead&#x27;s sensilla"},"a-p4":{"t":"p4","f":"4th palpal segment","d":"Fourth segment of the palp, often short.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-p5":{"t":"p5","f":"5th palpal segment","d":"Distal segment of the palp, usually the longest; whether it is the longest is used in some keys.","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-eye":{"t":"eye","f":"compound eye","d":"Large compound eye on each side of the head. Its size and the distance between the eyes (interocular distance) are measured in descriptions.","g":"glossary.html#a-eye","l":""},"a-iod":{"t":"ioD","f":"interocular distance","d":"Narrowest distance between the two compound eyes across the frons.","g":"glossary.html#a-iod","l":""},"a-cl":{"t":"cl","f":"clypeus","d":"Sclerite on the front of the head between the antennae, above the base of the labrum.","g":"glossary.html#a-cl","l":""},"a-hel":{"t":"heL","f":"head length","d":"Measurement: length of the head from the vertex to the lower edge of the clypeus.","g":"glossary.html#a-hel","l":""},"a-hw":{"t":"hW","f":"head width","d":"Measurement: greatest width of the head across the eyes.","g":"glossary.html#a-hw","l":""},"a-el":{"t":"eL","f":"eye length","d":"Measurement: greatest length of the compound eye.","g":"glossary.html#a-el","l":""},"a-ew":{"t":"eW","f":"eye width","d":"Measurement: width of the compound eye.","g":"glossary.html#a-ew","l":""},"a-cll":{"t":"clL","f":"clypeus length","d":"Measurement: length of the clypeus.","g":"glossary.html#a-cll","l":""},"a-fil":{"t":"fIL","f":"1st flagellomere length","d":"Measurement: length of flagellomere 1 (antenna 3), compared with the labrum or other segments in many keys.","g":"glossary.html#antenna-3","l":"Antenna 3"},"a-pl":{"t":"pL","f":"palpus length","d":"Measurement: total length of the palp (p1–p5).","g":"glossary.html#palpal-formula","l":"Palpal formula"},"a-le":{"t":"le","f":"labrum-epipharynx","d":"Upper blade of the proboscis; its length (E) is the standard for comparing antenna 3 and palpal segments.","g":"glossary.html#labrum","l":"Labrum"},"a-md":{"t":"md","f":"mandible","d":"Paired blade-like mouthparts with fine teeth, used by females to cut the skin.","g":"glossary.html#a-md","l":""},"a-hy":{"t":"hy","f":"hypopharynx","d":"Median blade of the proboscis that carries the salivary channel.","g":"glossary.html#a-hy","l":""},"a-lb":{"t":"lb","f":"labium","d":"Lower lip that sheathes the other mouthparts and ends in two labella.","g":"glossary.html#a-lb","l":""},"a-ml":{"t":"ml","f":"maxillary lacinia","d":"Blade of the maxilla, toothed at the tip in blood-feeding females.","g":"glossary.html#a-ml","l":""},"a-pha":{"t":"pha","f":"pharynx","d":"Muscular tube behind the cibarium; its shape and armature are diagnostic.","g":"glossary.html#pharynx","l":"Pharynx"},"a-pht":{"t":"pht","f":"pharyngeal teeth","d":"Teeth, spines or ridges on the posterior part of the pharynx (pharyngeal armature).","g":"glossary.html#pharyngeal-armature","l":"Pharyngeal armature"},"a-cic":{"t":"cic","f":"cibarial chamber","d":"Chamber at the base of the mouthparts, in front of the pharynx, that carries the cibarial armature.","g":"glossary.html#cibarium","l":"Cibarium"},"a-ptt":{"t":"ptt","f":"posterior teeth","d":"Row of large horizontal teeth at the back of the cibarium (&#x27;hind teeth&#x27; of older keys).","g":"glossary.html#hind-teeth","l":"Hind teeth"},"a-antt":{"t":"antt","f":"anterior teeth","d":"Small vertical teeth in front of the posterior teeth (&#x27;fore teeth&#x27; of older keys).","g":"glossary.html#fore-teeth","l":"Fore teeth"},"a-ltt":{"t":"ltt","f":"lateral teeth","d":"Teeth at the sides of the cibarium, outside the main row.","g":"glossary.html#cibarium","l":"Cibarium"},"a-pp":{"t":"pp","f":"posterior protuberance","d":"Projection at the back of the cibarium, near the posterior bridge.","g":"glossary.html#cibarium","l":"Cibarium"},"a-psbr":{"t":"psbr","f":"posterior bridge","d":"Sclerotized bridge at the junction of cibarium and pharynx.","g":"glossary.html#cibarium","l":"Cibarium"},"a-scarc":{"t":"scarc","f":"sclerotized arch","d":"Chitinous arch crossing the cibarium; complete or incomplete in different groups.","g":"glossary.html#cibarial-arch","l":"Cibarial arch"},"a-scare":{"t":"scare","f":"sclerotized area","d":"Pigmented (sclerotized) patch in the middle of the cibarium; its shape and colour are used in keys.","g":"glossary.html#pigment-patch","l":"Pigment patch"},"a-latsc":{"t":"latsc","f":"lateral sclerite","d":"Sclerotized strip along each side of the cibarium.","g":"glossary.html#cibarium","l":"Cibarium"},"a-r1-r5":{"t":"R1–R5","f":"radial veins","d":"The five branches of the radius, numbered from the front margin of the wing.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-m1-m4":{"t":"M1–M4","f":"medial veins","d":"The four branches of the media, behind the radial veins.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-rm":{"t":"rm","f":"radio-medial cross-vein","d":"Short cross-vein joining radius and media near the wing base.","g":"glossary.html#a-rm","l":""},"a-alpha":{"t":"α (alpha)","f":"length of R2","d":"Wing index α: length of vein R2 from its fork to the wing margin.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-beta":{"t":"β (beta)","f":"length of R2+3","d":"Wing index β: length of the stem R2+3, from the fork of R2+3+4 to the fork of R2 and R3. Keys use the ratio α/β (R2/R2+3).","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-gamma":{"t":"γ (gamma)","f":"length of R2+3+4","d":"Wing index γ: length of the stem R2+3+4, from the r-m cross-vein to its fork.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-delta":{"t":"δ (delta)","f":"R1 tip to R2+3 fork","d":"Wing index δ: distance between the tip of R1 and the fork of R2+3; positive when R1 ends beyond the fork.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-epsilon":{"t":"ε (epsilon)","f":"length of R3","d":"Wing index ε: length of vein R3.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-theta":{"t":"θ (theta)","f":"length of R4","d":"Wing index θ: length of vein R4 from the fork of R2+3+4 to the wing margin.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-pi":{"t":"π (pi)","f":"distance between forks","d":"Wing index π: distance between the fork of R2+3+4 and the fork of M1+2.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-r2":{"t":"R2","f":"radial vein 2","d":"Second branch of the radius; its length is wing index α.","g":"glossary.html#r2-r2-3","l":"R2/R2+3"},"a-wing-length":{"t":"length","f":"wing length","d":"Measurement: from the wing base to the tip.","g":"glossary.html#a-wing-length","l":""},"a-wing-width":{"t":"width","f":"wing width","d":"Measurement: greatest width of the wing.","g":"glossary.html#a-wing-width","l":""},"a-terg":{"t":"terg","f":"tergite","d":"Dorsal plate of an abdominal segment (numbered 1st–10th).","g":"glossary.html#abdominal-tergites-2-6","l":"Abdominal tergites 2-6"},"a-st":{"t":"st","f":"sternite","d":"Ventral plate of an abdominal segment.","g":"glossary.html#a-st","l":""},"a-cercus":{"t":"cercus","f":"cercus (pl. cerci)","d":"Paired terminal appendage at the tip of the abdomen, above the 10th sternite.","g":"glossary.html#a-cercus","l":""},"a-terminal-knob":{"t":"terminal knob","f":"terminal knob (head) of spermatheca","d":"Small knob at the apex of the spermatheca, often set in a neck; its shape is used in keys.","g":"glossary.html#head-of-spermatheca","l":"Head of spermatheca"},"a-individual-duct":{"t":"individual duct","f":"individual spermathecal duct","d":"Duct leading from each spermatheca; joins its partner to form the common duct.","g":"glossary.html#spermathecal-ducts","l":"Spermathecal ducts"},"a-common-duct":{"t":"common duct","f":"common spermathecal duct","d":"Short duct formed by the union of the two individual ducts.","g":"glossary.html#spermathecal-ducts","l":"Spermathecal ducts"},"a-stem":{"t":"stem","f":"fork stem","d":"Median stem of the genital furca (genital fork).","g":"glossary.html#genital-furca","l":"Genital furca"},"a-furca":{"t":"furca","f":"genital furca","d":"Fork-shaped sclerite of the 9th segment in females, supporting the genital opening.","g":"glossary.html#genital-furca","l":"Genital furca"},"a-gon":{"t":"gon","f":"gonopod","d":"Small appendage of the 8th segment in females (8th gonopod).","g":"glossary.html#a-gon","l":""},"a-insula":{"t":"insula","f":"","d":"Sclerotized area of the 8th segment near the genital opening in females.","g":"glossary.html#a-insula","l":""},"a-gonostylus":{"t":"gonostylus","f":"gonostyle (style)","d":"Distal segment of the male clasper, carrying the large spines.","g":"glossary.html#style","l":"Style"},"a-gonocoxite":{"t":"gonocoxite","f":"gonocoxite (coxite)","d":"Basal segment of the male clasper.","g":"glossary.html#coxite","l":"Coxite"},"a-paramere":{"t":"paramere","f":"","d":"Paired median appendage of the male genitalia, often with setae and lobes.","g":"glossary.html#paramere","l":"Paramere"},"a-parameral-sheath":{"t":"parameral sheath","f":"parameral sheath (aedeagus)","d":"Sclerotized sheath around the end of the aedeagal ducts.","g":"glossary.html#aedeagus","l":"Aedeagus"},"a-aedeagal-ducts":{"t":"aedeagal ducts","f":"aedeagal ducts (genital filaments)","d":"Paired ducts from the sperm pump to the tip of the parameral sheath; their length and tip shape are diagnostic.","g":"glossary.html#genital-filaments","l":"Genital filaments"},"a-sperm-pump":{"t":"sperm pump","f":"sperm pump (genital pump)","d":"Bulb-shaped pump inside the abdomen that pushes sperm along the aedeagal ducts.","g":"glossary.html#genital-pump","l":"Genital pump"},"a-ejac-apodeme":{"t":"ejaculatory apodeme","f":"","d":"Rod-like apodeme attached to the sperm pump.","g":"glossary.html#genital-pump","l":"Genital pump"},"a-epandrial-lobe":{"t":"epandrial lobe","f":"epandrial lobe (surstyle)","d":"Paired lateral lobe below the clasper (&#x27;surstyle&#x27; or &#x27;lateral lobe&#x27; of older keys).","g":"glossary.html#surstyle","l":"Surstyle"},"a-gonostyle-spines":{"t":"spines of gonostyle","f":"apical, external and internal spines","d":"Large spines of the gonostyle. Their number and position (apical, upper and lower external, internal) are key characters for subgenera.","g":"glossary.html#style","l":"Style"},"a-ste9":{"t":"9th ste","f":"9th sternite","d":"Ventral plate of the 9th segment of the male.","g":"glossary.html#a-ste9","l":""},"a-ter10":{"t":"10th ter","f":"10th tergite","d":"Dorsal plate of the 10th segment of the male.","g":"glossary.html#a-ter10","l":""},"a-ste10":{"t":"10th ste","f":"10th sternite","d":"Ventral plate of the 10th segment of the male.","g":"glossary.html#a-ste10","l":""},"a-f":{"t":"f","f":"fold","d":"Transverse fold (ridge) of the pharynx wall, seen in the posterior part of the pharynx.","g":"glossary.html#pharynx","l":"Pharynx"},"a-asc":{"t":"as","f":"ascoid","d":"Hyaline sensory rod (geniculated spine) on a flagellomere; the number per flagellomere gives the ascoidal (antennal) formula.","g":"glossary.html#ascoid","l":"Ascoid"},"a-ias":{"t":"ias","f":"internal ascoid","d":"The inner of the two ascoids on a flagellomere; its position on fI is recorded in descriptions.","g":"glossary.html#ascoid","l":"Ascoid"},"a-ap":{"t":"ap","f":"apical papilla","d":"Papilla at the tip of a flagellomere.","g":"glossary.html#papilla","l":"Papilla"},"a-pap":{"t":"pap","f":"preapical papilla","d":"Papilla just before the tip of a flagellomere.","g":"glossary.html#papilla","l":"Papilla"},"a-mp":{"t":"mp","f":"median papilla","d":"Papilla in the middle of a flagellomere.","g":"glossary.html#papilla","l":"Papilla"},"a-bp":{"t":"bp","f":"basal papilla","d":"Papilla near the base of a flagellomere.","g":"glossary.html#papilla","l":"Papilla"},"a-pasp":{"t":"pasp","f":"preascoidal papilla","d":"Papilla just before (basal to) the ascoid.","g":"glossary.html#papilla","l":"Papilla"},"a-sp":{"t":"sp","f":"spiniform papilla","d":"Spine-shaped papilla on an apical flagellomere.","g":"glossary.html#papilla","l":"Papilla"},"a-ss":{"t":"ss","f":"simple seta","d":"Ordinary hair (seta) on a flagellomere or palpal segment; position and number are recorded in descriptions.","g":"glossary.html#a-ss","l":""},"a-fiii":{"t":"fIII","f":"3rd flagellomere","d":"= &#x27;antenna 5&#x27; of older keys; papillae on fIII separate some species (e.g. <i>P. argentipes</i> and <i>P. philippinensis</i>).","g":"glossary.html#papilla","l":"Papilla"},"a-ns":{"t":"Ns","f":"Newstead&#x27;s sensilla","d":"Club-shaped sensilla on the palp, usually grouped on p3.","g":"glossary.html#newstead-s-sensilla","l":"Newstead&#x27;s sensilla"},"a-anp":{"t":"anp","f":"anepimeron","d":"Sclerite of the side (pleuron) of the thorax, behind the upper and lower anepisternum. Bears the anepimeral setae, or scales in <i>Grassomyia</i>.","g":"glossary.html#anepimeron-scales","l":"Anepimeron scales"},"a-apn":{"t":"apn","f":"antepronotum","d":"Front part of the pronotum, behind the neck.","g":"glossary.html#a-apn","l":""},"a-asp":{"t":"as","f":"anterior spiracle","d":"Breathing opening (spiracle) on the front of the thorax. Not to be confused with as = ascoid on the antenna.","g":"glossary.html#a-asp","l":""},"a-at":{"t":"at","f":"anatergite","d":"Sclerite below the postnotum at the back of the thorax.","g":"glossary.html#a-at","l":""},"a-csc":{"t":"csc","f":"cervical sclerite","d":"Sclerite of the neck (cervix), with a pair of sensilla.","g":"glossary.html#a-csc","l":""},"a-hal":{"t":"hal","f":"halter","d":"Knob-like hind wing used for balance in flight.","g":"glossary.html#a-hal","l":""},"a-kep":{"t":"kep","f":"katepimeron","d":"Lower sclerite of the pleuron behind the katepisternum.","g":"glossary.html#a-kep","l":""},"a-kes":{"t":"kes","f":"katepisternum","d":"Large lower sclerite of the side of the thorax, above the middle leg.","g":"glossary.html#a-kes","l":""},"a-kt":{"t":"kt","f":"katatergite","d":"Small sclerite below the postnotum, near the posterior spiracle.","g":"glossary.html#a-kt","l":""},"a-las":{"t":"las","f":"lower anepisternum","d":"Lower part of the anepisternum, in front of the anepimeron; may bear lower anepisternal setae.","g":"glossary.html#a-las","l":""},"a-mnt":{"t":"mnt","f":"metanotum","d":"Dorsal sclerite of the third thoracic segment; may bear metanotal setae.","g":"glossary.html#a-mnt","l":""},"a-mscx":{"t":"mscx","f":"mesocoxa","d":"Coxa (first leg segment) of the middle leg.","g":"glossary.html#a-mscx","l":""},"a-msf":{"t":"msf","f":"mesofurca","d":"Internal fork-shaped apodeme of the mesothorax.","g":"glossary.html#a-msf","l":""},"a-mtcx":{"t":"mtcx","f":"metacoxa","d":"Coxa of the hind leg.","g":"glossary.html#a-mtcx","l":""},"a-mtf":{"t":"mtf","f":"metafurca","d":"Internal fork-shaped apodeme of the metathorax; whether its vertical arms are united or separate is recorded in descriptions.","g":"glossary.html#a-mtf","l":""},"a-mtp":{"t":"mtp","f":"metepimeron","d":"Posterior pleural sclerite of the metathorax; may bear metepimeral setae.","g":"glossary.html#a-mtp","l":""},"a-mts":{"t":"mts","f":"metepisternum","d":"Anterior pleural sclerite of the metathorax; may bear metepisternal setae.","g":"glossary.html#a-mts","l":""},"a-pem":{"t":"pem","f":"proepimeron","d":"Posterior pleural sclerite of the prothorax; may bear proepimeral setae.","g":"glossary.html#a-pem","l":""},"a-pes":{"t":"pes","f":"proepisternum","d":"Anterior pleural sclerite of the prothorax.","g":"glossary.html#a-pes","l":""},"a-pnt":{"t":"pnt","f":"postnotum","d":"Hind part of the mesonotum, behind the scutellum.","g":"glossary.html#a-pnt","l":""},"a-ppn":{"t":"ppn","f":"postpronotum","d":"Hind part of the pronotum.","g":"glossary.html#a-ppn","l":""},"a-pps":{"t":"pps","f":"protuberance of the prosternum","d":"Projection of the prosternum between the front legs.","g":"glossary.html#a-pps","l":""},"a-prcx":{"t":"prcx","f":"procoxa","d":"Coxa of the front leg.","g":"glossary.html#a-prcx","l":""},"a-prf":{"t":"prf","f":"profurca","d":"Internal fork-shaped apodeme of the prothorax.","g":"glossary.html#a-prf","l":""},"a-ps":{"t":"ps","f":"posterior spiracle","d":"Breathing opening at the back of the thorax.","g":"glossary.html#a-ps","l":""},"a-psct":{"t":"psct","f":"prescutum","d":"Front part of the mesonotum; may bear prescutal setae.","g":"glossary.html#a-psct","l":""},"a-pt":{"t":"pt","f":"paratergite","d":"Small sclerite at the side of the mesonotum; may bear paratergital setae.","g":"glossary.html#a-pt","l":""},"a-sclt":{"t":"sclt","f":"scutellum","d":"Rounded sclerite at the back of the mesonotum; bears scutellar setae.","g":"glossary.html#a-sclt","l":""},"a-sct":{"t":"sct","f":"scutum","d":"Main dorsal plate of the mesothorax.","g":"glossary.html#a-sct","l":""},"a-uas":{"t":"uas","f":"upper anepisternum","d":"Upper part of the anepisternum; may bear upper anepisternal setae.","g":"glossary.html#a-uas","l":""},"a-vcsc":{"t":"vcsc","f":"ventrocervical sclerite","d":"Sclerite on the underside of the neck; may bear ventrocervical sensilla.","g":"glossary.html#a-vcsc","l":""},"a-win":{"t":"win","f":"wing","d":"Base of the wing.","g":"glossary.html#a-win","l":""},"a-anps":{"t":"anps","f":"anepimeral setae","d":"Setae on the anepimeron; their presence or absence is recorded in descriptions.","g":"glossary.html#anepimeron-scales","l":"Anepimeron scales"},"a-dcs":{"t":"dcs","f":"dorsocentral setae","d":"Setae in rows along the middle of the scutum.","g":"glossary.html#a-dcs","l":""},"a-lass":{"t":"lass","f":"lower anepisternal setae","d":"Setae on the lower anepisternum (presence or absence recorded).","g":"glossary.html#a-lass","l":""},"a-mnts":{"t":"mnts","f":"metanotal setae","d":"Setae on the metanotum.","g":"glossary.html#a-mnts","l":""},"a-mtps":{"t":"mtps","f":"metepimeral setae","d":"Setae on the metepimeron (presence or absence recorded).","g":"glossary.html#a-mtps","l":""},"a-mtss":{"t":"mtss","f":"metepisternal setae","d":"Setae on the metepisternum (presence and number recorded).","g":"glossary.html#a-mtss","l":""},"a-pems":{"t":"pems","f":"proepimeral setae","d":"Setae on the proepimeron (presence or absence recorded).","g":"glossary.html#a-pems","l":""},"a-pscts":{"t":"pscts","f":"prescutal setae","d":"Setae on the prescutum.","g":"glossary.html#a-pscts","l":""},"a-psus":{"t":"psus","f":"postsutural setae","d":"Setae on the scutum behind the transverse suture.","g":"glossary.html#a-psus","l":""},"a-sas":{"t":"sas","f":"supra-alar setae","d":"Setae above the wing base.","g":"glossary.html#a-sas","l":""},"a-sctls":{"t":"sctls","f":"scutellar setae","d":"Setae on the scutellum.","g":"glossary.html#a-sctls","l":""},"a-uass":{"t":"uass","f":"upper anepisternal setae","d":"Setae on the upper anepisternum (presence or absence recorded).","g":"glossary.html#a-uass","l":""},"a-vcs":{"t":"vcs","f":"ventrocervical sensilla","d":"Sensilla on the ventrocervical sclerite (presence or absence recorded).","g":"glossary.html#a-vcs","l":""}};
